#include "motor_control.h"
#include "PositionMotor.h"
#include "SpeedMotor.h"
#include "main.h"
#include <cstdio>

#define PWM_PERIOD 3199
#define SPEED_WINDOW 65
#define ENCODER_TIMER htim2
// Hardware handles generated by CubeMXs
extern TIM_HandleTypeDef htim5; // PWM Timer
extern TIM_HandleTypeDef ENCODER_TIMER; // Encoder Timer
extern I2C_HandleTypeDef hi2c1; // I2C Handle

// --- SWD Live Variables (Accessible via pyocd) ---
extern "C" {
// Elbow Position Motor (used by Python SWD Angle Tuner)
    volatile float g_kp = 0.0f;
    volatile float g_ki = 0.0f;
    volatile float g_kd = 0.0f;
    volatile float g_target_angle = 2048.0f;
    volatile float g_current_angle = 0.0f;
    volatile float g_elbow_duty = 0.0f;

    // Drive Speed Motor (independent SWD variables)
    volatile float g_drive_kp = 0.0f;
    volatile float g_drive_ki = 0.0f;
    volatile float g_drive_kd = 0.0f;
    volatile float g_target_rpm = 0.0f;
    volatile float g_current_rpm = 0.0f;
    volatile float g_drive_duty = 0.0f;

    volatile uint32_t g_raw_ticks = 0; // Exposed to pyOCD for live debugging
}

const float ELBOW_MIN_POS = 200.0f;
const float ELBOW_MAX_POS = 3800.0f;
#define AS5600_I2C_ADDR         (0x36 << 1)
#define AS5600_RAW_ANGLE_REG    0x0C

static float last_valid_position = 2048.0f;

// --- Speed Motor (PA8 / TIM1_CH1 PWM, PB4 DIR) ---
static SpeedMotor driveMotor(&htim5, TIM_CHANNEL_2, PWM_PERIOD,
                              GPIOG, GPIO_PIN_9, 0,
                              2.0f, 1.0f, 0.0f);

// --- Position Motor (PA9 / TIM1_CH2 PWM, PB2 DIR) ---
static PositionMotor elbowMotor(&htim5, TIM_CHANNEL_3, PWM_PERIOD,
                                 GPIOB, GPIO_PIN_2,
                                 4095.0f,
                                 1.0f, 0.2f, 0.0f);

static float ReadElbowAbsolutePosition(void) {
    uint8_t buffer[2] = {0};

    HAL_StatusTypeDef status = HAL_I2C_Mem_Read(&hi2c1,
            AS5600_I2C_ADDR, AS5600_RAW_ANGLE_REG, I2C_MEMADD_SIZE_8BIT,
            buffer, 2, 2);

    if (status == HAL_OK) {
        uint16_t raw_val = ((uint16_t)buffer[0] << 8) | buffer[1];
        last_valid_position = (float)(raw_val & 0x0FFF);
    }

    return last_valid_position;
}

static float ReadDriveSpeedRPM(float dt_seconds) {
//    static uint32_t prev_count = 0;
//    static bool first_run = true;
//
//	uint32_t current_count = __HAL_TIM_GET_COUNTER(&htim5);
//	g_raw_ticks = current_count;
//
//	if (first_run) {
//		prev_count = current_count;
//		first_run = false;
//		return 0.0f;
//	}
//
//    int32_t delta_ticks = (int32_t)(current_count - prev_count);
//    prev_count = current_count;
//
//    const float ENCODER_PPR = 13.0f;
//    const float GEAR_RATIO = 181.0f;
//    const float ENCODER_MODE_MULT = 4.0f;
//    const float TICKS_PER_REV = ENCODER_PPR * GEAR_RATIO * ENCODER_MODE_MULT;
//
//    float revolutions = (float)delta_ticks / TICKS_PER_REV;
//    return (revolutions / dt_seconds) * 60.0f;
    static uint32_t history[SPEED_WINDOW];
	static uint32_t idx = 0;
	static uint32_t filled = 0;

	uint32_t current_count = __HAL_TIM_GET_COUNTER(&ENCODER_TIMER);
	g_raw_ticks = current_count;

	uint16_t oldest = history[idx];      // count from SPEED_WINDOW samples ago
	history[idx] = current_count;
	idx = (idx + 1) % SPEED_WINDOW;

	if (filled < SPEED_WINDOW) {         // buffer not full yet
		filled++;
		return 0.0f;
	}

	int32_t delta_ticks = (int16_t)(current_count - oldest);
	const float TICKS_PER_REV = 13.0f * 181.0f * 4.0f;
	float window_s = SPEED_WINDOW * dt_seconds;
	return ((float)delta_ticks / TICKS_PER_REV) / window_s * 60.0f;
}

void MotorControl_Init(void) {
    HAL_TIM_Encoder_Start(&ENCODER_TIMER, TIM_CHANNEL_ALL);
    driveMotor.begin();
}

void Elbow_Control_Init(void) {
    elbowMotor.disableWrap();
    elbowMotor.begin();

    // Sync initial target to current AS5600 reading so the arm holds still on boot
    g_current_angle = ReadElbowAbsolutePosition();
    g_target_angle = g_current_angle;
}

void MotorControl_SetParams(float kp, float ki, float kd, float targetRpm) {
    driveMotor.setGains(kp, ki, kd);
    driveMotor.setTargetSpeed(targetRpm);
}

void MotorControl_Update(float dt_seconds) {
    driveMotor.setGains(g_drive_kp, g_drive_ki, g_drive_kd);
    driveMotor.setTargetSpeed(g_target_rpm);

    g_current_rpm = ReadDriveSpeedRPM(dt_seconds);
    driveMotor.update(g_current_rpm, dt_seconds);

    g_drive_duty = driveMotor.getOutput();
}

void Elbow_Control_Update(float target_position, float dt_seconds) {
    elbowMotor.setGains(g_kp, g_ki, g_kd);

    if (target_position > ELBOW_MAX_POS) target_position = ELBOW_MAX_POS;
    if (target_position < ELBOW_MIN_POS) target_position = ELBOW_MIN_POS;
    g_target_angle = target_position;

    g_current_angle = ReadElbowAbsolutePosition();
    elbowMotor.setTargetPosition(target_position);
    elbowMotor.update(g_current_angle, dt_seconds);

    g_elbow_duty = elbowMotor.getOutput();
}
